class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self.limit_bytes: float = monthly_limit_mib * 1024 * 1024
        # Tracks current files uploaded per month: month -> {name: size_bytes}
        self._uploads: dict[str, dict[str, int]] = {}
        # Tracks historical quota consumed per month (deletions do not refund quota): month -> int
        self._used: dict[str, int] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """month is a string like '2026-01'."""
        month_files = self._uploads.setdefault(month, {})
        current_used = self._used.get(month, 0)

        # Requirement 1: Uploading again a file with the same name in the same month
        # does not count towards the limit a second time.
        if name in month_files:
            return

        # Check if new upload exceeds limit
        if current_used + size_bytes > self.limit_bytes:
            raise ValueError(
                f"Upload of {size_bytes} bytes exceeds the monthly quota for {month}."
            )

        month_files[name] = size_bytes
        self._used[month] = current_used + size_bytes

    def delete(self, name: str, month: str) -> None:
        """Delete a file from the given month. Does not refund quota."""
        month_files = self._uploads.get(month)
        if month_files and name in month_files:
            del month_files[name]

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        return self._used.get(month, 0)
```

